List<Message> batch = [];
foreach (Message message in page.Messages)
    batch.Add(message);

Dictionary<string, string> cacheHits = [];
foreach (Message message in batch)
{
    string id = message.MessageId;
    string? cached = redis.StringGet($"dedup:{id}");
    if (cached is not null)
        cacheHits[id] = cached;
}

HashSet<string> seenIds = [.. batch.Select(m => m.MessageId)];
Queue<Message> retry = [];
foreach (Message message in batch)
{
    if (!cacheHits.ContainsKey(message.MessageId))
        retry.Enqueue(message);
}

while (retry.Count > 0)
    Process(retry.Dequeue());

