readonly record struct TenantId(string Value);

class TenantIdComparer : IEqualityComparer<TenantId>
{
    public bool Equals(TenantId x, TenantId y) =>
        x.Value.Equals(y.Value, StringComparison.Ordinal);
    public int GetHashCode(TenantId obj) =>
        obj.Value.GetHashCode(StringComparison.Ordinal);
}

var tenants = new Dictionary<TenantId, string>(new TenantIdComparer());
